/* Get the PWM_EGTM version. */
ACS_APP_VERSION_t PWM_EGTM_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = PWM_EGTM_MAJOR_VERSION;
  version.minor = PWM_EGTM_MINOR_VERSION;
  version.patch = PWM_EGTM_PATCH_VERSION;

  return version;
}

/* Function to initialize the EGTM PWM functionality by the configuration made in GUI. */
PWM_EGTM_STATUS_t PWM_EGTM_Init(PWM_EGTM_t * handle)
{
  PWM_EGTM_STATUS_t status = PWM_EGTM_STATUS_SUCCESS;

  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  if (!handle->app_is_initialized)
  {
    /* Init function of the required APP is called */
    if (EGTM_GENERIC_Init(handle->egtm_generic_handle) == EGTM_GENERIC_STATUS_SUCCESS)
    {

      /* Initializes the EGTM module for PWM  */
      IfxEgtm_Pwm_init(&handle->egtm_pwm, &handle->egtm_pwm_ch, (IfxEgtm_Pwm_Config *)handle->app_config->lld_config);

      /* Set interrupt notification */
      if (handle->egtm_pwm.subModule == IfxEgtm_Pwm_SubModule_atom)
      {
        IfxEgtm_Atom_Ch_setNotification(&(handle->egtm_pwm.clusterSFR->ATOM), (IfxEgtm_Atom_Ch)handle->egtm_pwm.channels->timerCh, IfxEgtm_IrqMode_pulseNotify,
                                       handle->app_config->lld_interrupt_config->ccu0_interrupt, handle->app_config->lld_interrupt_config->ccu0_interrupt);
      }
      else
      {
        IfxEgtm_Tom_Ch_setNotification(&(handle->egtm_pwm.clusterSFR->TOM), (IfxEgtm_Tom_Ch)handle->egtm_pwm.channels->timerCh, IfxEgtm_IrqMode_pulseNotify,
                                      handle->app_config->lld_interrupt_config->ccu0_interrupt, handle->app_config->lld_interrupt_config->ccu0_interrupt);
      }
      /* Configures GPIO if enabled in the APP */
      if (handle->app_config->lld_pin_config != NULL_PTR)
      {
        IfxPort_setPinMode((Ifx_P *)handle->app_config->lld_pin_config->port, (uint8)handle->app_config->lld_pin_config->pinIndex,
                           (IfxPort_Mode)handle->app_config->lld_pin_config->mode);
        IfxPort_setPinPadDriver((Ifx_P *)handle->app_config->lld_pin_config->port, (uint8)handle->app_config->lld_pin_config->pinIndex,
                           (IfxPort_PadDriver)handle->app_config->lld_pin_config->padDriver);
      }

      /* Start the PWM if start after initialization is enabled */
      if (handle->app_config->init_start)
      {
        IfxEgtm_Pwm_startSyncedChannels(&handle->egtm_pwm);
      }

      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = PWM_EGTM_STATUS_FAILURE;
    }
  }
  return status;
}

/* Function to start the PWM signal generation. */
PWM_EGTM_STATUS_t PWM_EGTM_Start(PWM_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_startSyncedChannels(&handle->egtm_pwm);
  return PWM_EGTM_STATUS_SUCCESS;
}

/* Function to stop the PWM signal generation. */
PWM_EGTM_STATUS_t PWM_EGTM_Stop(PWM_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_stopSyncedChannels(&handle->egtm_pwm);
  return PWM_EGTM_STATUS_SUCCESS;
}

/* Function to change the frequency of the PWM signal based on the input parameter. */
PWM_EGTM_STATUS_t PWM_EGTM_SetFreq(PWM_EGTM_t *handle, float32 frequency)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_updateFrequency(&handle->egtm_pwm, frequency);
  return PWM_EGTM_STATUS_SUCCESS;
}

/* Function to change the duty cycle of the PWM signal based on the input parameter. */
PWM_EGTM_STATUS_t PWM_EGTM_SetDuty(PWM_EGTM_t *handle, float32 dutycycle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_updateChannelsDuty(&handle->egtm_pwm, &dutycycle);
  return PWM_EGTM_STATUS_SUCCESS;
}

/* Function to change the frequency and the duty cycle of the PWM signal based on the input parameters. */
PWM_EGTM_STATUS_t PWM_EGTM_SetFreqAndDuty(PWM_EGTM_t *handle, float32 frequency, float32 dutycycle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_updateFrequency(&handle->egtm_pwm, frequency);
  IfxEgtm_Pwm_updateChannelsDuty(&handle->egtm_pwm, &dutycycle);
  return PWM_EGTM_STATUS_SUCCESS;
}

/* Function to check the status of PWM state. */
PWM_EGTM_STATUS_t PWM_EGTM_GetStatus(PWM_EGTM_t *handle, PWM_EGTM_RUNNING_STATUS_t *pwmstatus)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEgtm_Pwm_ChannelState state;
  state = IfxEgtm_Pwm_getChannelState(&handle->egtm_pwm, handle->egtm_pwm.channels->timerCh);
  *pwmstatus = (PWM_EGTM_RUNNING_STATUS_t)state;
  return PWM_EGTM_STATUS_SUCCESS;
}

